            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x), (y+1,x), (y,x-1), (y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 3 and (ny,nx) not in seen:
                        seen.add((ny,nx))
                        q.append((ny,nx))
            rs = [y for y, _ in cells]
            cs = [x for _, x in cells]
            panels.append((min(rs), max(rs), min(cs), max(cs)))

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2:
                continue
            if not any(r0 <= r <= r1 and c0 <= c <= c1 for r0, r1, c0, c1 in panels):
                continue
            for nr in range(max(0, r - 1), min(h, r + 2)):
                for nc in range(max(0, c - 1), min(w, c + 2)):
                    if grid[nr][nc] != 2:
                        out[nr][nc] = 1
    return out
